"""업체 페이지와 지역 페이지가 같이 쓰는 머리글·바닥글."""
from hdr import header as _hdr
import re as _re
def band(s):
    """제목(h1)과 요약(.sum)을 남색 상단 띠로 감싸 모든 목록 페이지가 같은 모양이 되게 합니다."""
    return _re.sub(r'(<h1>.*?</h1>\s*<p class="sum">.*?</p>)', r'<div class="pgband">\1</div>', s, count=1, flags=_re.S)
